			dw fn_nx_reg, lit_22, lit_0
			dw fn_nx_reg, lit_23, lit_0

			; L2.cls 16: Out &H123B, 2
			dw kw_out, lit_4667, lit_2

			; L2.cls 18: vis = 19 : pb = 38
			dw kw_ltov, 19, var_l2_vis
			dw kw_ltov, 38, var_l2_pb

			; L2.cls 19: Rect 0, 0, 256, 192, 0
			dw p_l2_rect_c, lit_0, lit_0, lit_256, lit_192, lit_0

			; L2.cls 20: vis = 16 : pb = 32
			dw kw_ltov, 16, var_l2_vis
			dw kw_ltov, 32, var_l2_pb

