			; L2.cls 96: Dim j As Integer

			; L2.cls 97: For j = y To y + h - 1
			dw kw_vtov, var_l2_rect_y, var_l2_rect_j
			dw kw_add, var_l2_rect_y, var_l2_rect_h, tmp0
			dw kw_addl, tmp0, -1, for163_l
