			; L2.cls 104: If x >= 0 And x < 256 And y >= 0 And y < 192 Then Span x, y, 1, c
			dw kw_scpgevl, var_l2_plot_x, 0
			dw kw_ftov, tmp0
			dw kw_scpltvl, var_l2_plot_x, 256
			dw kw_ftov, tmp1
